using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class LampPassageWalk {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));
 static object Travel(CharacterController cc,Vector3 a,Vector3 b){cc.enabled=false;cc.transform.position=a+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();float remaining=99;for(int i=0;i<200;i++){var d=b-cc.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.03f)break;cc.Move(d.normalized*Mathf.Min(.035f,remaining)+Vector3.down*.025f);}return new{pass=remaining<.10f,remaining,end=cc.transform.position.ToString("F4")};}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();var cc=ts.Select(t=>t.GetComponent<CharacterController>()).Single(c=>c);var save=cc.transform.position;bool enabled=cc.enabled;var e02=ts.Single(t=>t.name=="B4_E02_TaskLightPole_13");var c02=ts.Single(t=>t.name=="B4_C02_TaskLightPole_15");var oldPos=e02.position;var tests=new List<object>();var a=new Vector3(125.16f,-66,-1.30f);var b=new Vector3(125.16f,-66,1.40f);try{var before=Travel(cc,a,b);tests.Add(new{id="E02_pole_to_service_bay_before",result=before});if(!(bool)before.GetType().GetProperty("pass").GetValue(before)){e02.position+=Vector3.left*.20f;PrefabUtility.RecordPrefabInstancePropertyModifications(e02);Physics.SyncTransforms();}tests.Add(new{id="E02_pole_to_service_bay_forward",result=Travel(cc,a,b)});tests.Add(new{id="E02_pole_to_service_bay_reverse",result=Travel(cc,b,a)});foreach(var t in new[]{e02,c02}){float right=t==e02?.36f:.98f;var p=t.TransformPoint(new Vector3(-.98f,0,.43f));var q=t.TransformPoint(new Vector3(right,0,.43f));tests.Add(new{id=t.name+"_front_forward",result=Travel(cc,p,q)});tests.Add(new{id=t.name+"_front_reverse",result=Travel(cc,q,p)});}}finally{cc.enabled=false;cc.transform.position=save;cc.enabled=enabled;Physics.SyncTransforms();}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{lampMove=(e02.position-oldPos).ToString("F4"),oldPosition=oldPos.ToString("F4"),newPosition=e02.position.ToString("F4"),tests};File.WriteAllText(H+"local_walk.json",JsonConvert.SerializeObject(result,Formatting.Indented));EditorSceneManager.OpenScene(s.path);return result;}
}
